/* Utility-based agents + A* navigation + reservations + local separation.
   Pure simulation: positions, choices and paths are independent of rendering. */
const distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
function inside(p,poly){let yes=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let a=poly[i],b=poly[j];if((a.z>p.z)!==(b.z>p.z)&&p.x<(b.x-a.x)*(p.z-a.z)/(b.z-a.z)+a.x)yes=!yes}return yes}
class Heap{constructor(){this.a=[]}push(v){let a=this.a;a.push(v);let i=a.length-1;while(i){let p=(i-1)>>1;if(a[p].f<=v.f)break;a[i]=a[p];i=p}a[i]=v}pop(){let a=this.a,r=a[0],v=a.pop();if(a.length){let i=0;while(i*2+1<a.length){let j=i*2+1;if(j+1<a.length&&a[j+1].f<a[j].f)j++;if(a[j].f>=v.f)break;a[i]=a[j];i=j}a[i]=v}return r}get length(){return this.a.length}}
export class NavigationGrid{
 constructor(bounds,obstacles=[],polygons=[],step=.38){this.bounds=bounds;this.step=step;this.cols=Math.max(2,Math.ceil((bounds.maxX-bounds.minX)/step));this.rows=Math.max(2,Math.ceil((bounds.maxZ-bounds.minZ)/step));this.blocked=new Uint8Array(this.cols*this.rows);for(let i=0;i<this.blocked.length;i++){let p=this.point(i);if(obstacles.some(o=>distance(p,o)<o.radius)||polygons.some(poly=>inside(p,poly)))this.blocked[i]=1}}
 point(i){return{x:this.bounds.minX+(i%this.cols+.5)*this.step,z:this.bounds.minZ+(Math.floor(i/this.cols)+.5)*this.step}}
 index(p){let x=Math.floor((p.x-this.bounds.minX)/this.step),z=Math.floor((p.z-this.bounds.minZ)/this.step);return x<0||z<0||x>=this.cols||z>=this.rows?-1:z*this.cols+x}
 open(i,extra){return i>=0&&i<this.blocked.length&&!this.blocked[i]&&!extra?.has(i)}
 nearest(p,extra){let i=this.index(p);if(this.open(i,extra))return i;let best=-1,d=Infinity;for(let k=0;k<this.blocked.length;k++)if(this.open(k,extra)){let v=distance(p,this.point(k));if(v<d){d=v;best=k}}return best}
 walkable(p){return this.open(this.index(p))}
 clearLine(a,b,extra){let n=Math.ceil(distance(a,b)/(this.step*.3));for(let j=0;j<=n;j++){let t=n?j/n:0;if(!this.open(this.index({x:a.x+(b.x-a.x)*t,z:a.z+(b.z-a.z)*t}),extra))return false}return true}
 findPath(from,to,extra){let start=this.nearest(from),goal=this.nearest(to,extra);if(start<0||goal<0)return[];let costs=new Float64Array(this.blocked.length).fill(Infinity),parent=new Int32Array(this.blocked.length).fill(-1),closed=new Uint8Array(this.blocked.length),heap=new Heap();costs[start]=0;let dest=this.point(goal);heap.push({i:start,f:distance(this.point(start),dest)});while(heap.length){let {i}=heap.pop();if(closed[i])continue;if(i===goal){let path=[];for(let p=goal;p>=0;p=parent[p]){path.push(this.point(p));if(p===start)break}path.reverse();let smooth=[path[0]],k=0;while(k<path.length-1){let j=path.length-1;while(j>k+1&&!this.clearLine(path[k],path[j],extra))j--;smooth.push(path[j]);k=j}return smooth}closed[i]=1;let x=i%this.cols,z=Math.floor(i/this.cols);for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dz)continue;let nx=x+dx,nz=z+dz;if(nx<0||nz<0||nx>=this.cols||nz>=this.rows)continue;let j=nz*this.cols+nx;if(!this.open(j,extra)||closed[j])continue;if(dx&&dz&&(!this.open(z*this.cols+nx,extra)||!this.open(nz*this.cols+x,extra)))continue;let g=costs[i]+this.step*(dx&&dz?Math.SQRT2:1);if(g<costs[j]){costs[j]=g;parent[j]=i;heap.push({i:j,f:g+distance(this.point(j),dest)})}}}return[]}
}
export class BehaviourSimulation{
 constructor(agents,{random=Math.random,onAction=()=>{}}={}){this.random=random;this.onAction=onAction;this.agents=agents.map((a,i)=>({id:i,position:{x:a.position.x,z:a.position.z},needs:{energy:.65+i*.08,curiosity:.2+i*.16,work:.3+i*.1},personality:{diligence:.6+(i%2)*.4,social:.5+(i%3)*.15},state:'deciding',task:null,path:[],speed:.9+i*.09,moving:false,workAnimation:0,replans:0,decisions:0,blockedTime:0,recent:[],completed:0,wait:.1+i*.2}));this.reservations=new Map();this.sites=[];this.jobs=[];this.time=0;this.nav=null}
 configure(nav,sites){this.nav=nav;this.sites=sites;this.reservations.clear();for(let a of this.agents){let i=nav.nearest(a.position);if(i>=0&&!nav.walkable(a.position))a.position=nav.point(i);if(a.task?.siteId){let site=sites.find(s=>s.id===a.task.siteId);if(!site){a.task=null;a.state='deciding';a.path=[]}else{a.task.target=this.approach(site,a.position);this.reservations.set(site.id,a.id)}}if(a.task&&a.state==='walking')this.replan(a)}}
 approach(site,p){let best=Infinity,target=site.position;for(let j=0;j<8;j++){let a=j*Math.PI/4,r=site.radius+.38,c={x:site.position.x+Math.cos(a)*r,z:site.position.z+Math.sin(a)*r},i=this.nav.nearest(c);if(i<0)continue;let q=this.nav.point(i),d=distance(q,p);if(d<best){target=q;best=d}}return target}
 emit(kind,point,{agentId=null,priority=100,duration=2,metadata=null}={}){this.jobs.push({kind,target:{x:point.x,z:point.z},agentId,priority,duration,metadata});this.jobs.sort((a,b)=>b.priority-a.priority);if(this.jobs.length>8)this.jobs.length=8;for(let a of this.agents)if(agentId===null||a.id===agentId){if(a.task?.priority<priority||!a.task){this.release(a);a.task=null;a.state='deciding';a.wait=0;break}}}
 release(a){if(a.task?.siteId&&this.reservations.get(a.task.siteId)===a.id)this.reservations.delete(a.task.siteId)}
 replan(a,dynamic=false){if(!a.task||!this.nav)return;let occupied;if(dynamic){occupied=new Set();for(let b of this.agents)if(b!==a&&distance(b.position,a.task.target)>.45){let i=this.nav.index(b.position);if(i>=0)occupied.add(i)}}a.path=this.nav.findPath(a.position,a.task.target,occupied);if(a.path.length>1)a.path.shift();a.replans++;a.blockedTime=0;if(!a.path.length){if(a.task.siteId)a.recent=[a.task.siteId,...a.recent].slice(0,3);this.release(a);a.task=null;a.state='deciding';a.wait=1+this.random();return}a.state='walking'}
 choose(a){let jobIndex=this.jobs.findIndex(j=>j.agentId===null||j.agentId===a.id);let task;if(jobIndex>=0)task=this.jobs.splice(jobIndex,1)[0];else{let best=-Infinity;for(let site of this.sites){if(!site.available||this.reservations.has(site.id))continue;let repetition=a.recent.includes(site.id)?.5:1;let score=(site.kind==='rest'?(1-a.needs.energy)*2.5:site.kind==='water'?(1-site.moisture)*a.personality.diligence+a.needs.work:site.kind==='inspect'?a.needs.curiosity+.2:site.kind==='social'?a.personality.social+a.needs.curiosity*.4:a.needs.work*.8+.3)*repetition-(distance(a.position,site.position)*.045)+this.random()*.12;if(score>best){best=score;task={kind:site.kind,siteId:site.id,target:this.approach(site,a.position),duration:site.kind==='rest'?5:2.5+this.random()*2,priority:1}}}if(!task){let open=[];for(let i=0;i<this.nav.blocked.length;i++)if(!this.nav.blocked[i])open.push(i);if(!open.length)return;task={kind:'wander',target:this.nav.point(open[Math.floor(this.random()*open.length)]),duration:1,priority:0}}}
  a.decisions++;a.task=task;if(task.siteId)this.reservations.set(task.siteId,a.id);this.replan(a)
 }
 tick(dt){if(!this.nav)return;this.time+=dt;for(let site of this.sites)if(site.kind==='water')site.moisture=Math.max(0,site.moisture-dt*.004);for(let a of this.agents){a.moving=false;a.needs.energy=Math.max(.05,a.needs.energy-dt*.004);a.needs.curiosity=Math.min(1,a.needs.curiosity+dt*.008);a.needs.work=Math.min(1,a.needs.work+dt*.005);if(a.wait>0){a.wait-=dt;continue}if(!a.task){this.choose(a);if(!a.task)continue}if(a.state==='performing'){a.workAnimation+=dt;a.task.remaining-=dt;if(a.task.remaining<=0){let site=this.sites.find(s=>s.id===a.task.siteId);if(site){a.recent=[site.id,...a.recent].slice(0,3);if(site.kind==='water')site.moisture=1}if(a.task.kind==='rest')a.needs.energy=1;else{a.needs.curiosity=Math.max(0,a.needs.curiosity-.5);a.needs.work=Math.max(0,a.needs.work-.4)}this.onAction(a,a.task,site);a.completed++;this.release(a);a.task=null;a.state='deciding';a.wait=.5+this.random()*.8}continue}
   let dest=a.path[0];if(!dest){a.state='performing';a.task.remaining=a.task.duration;a.workAnimation=0;continue}let dx=dest.x-a.position.x,dz=dest.z-a.position.z,d=Math.hypot(dx,dz);if(d<.12){a.path.shift();continue}let vx=dx/d*a.speed,vz=dz/d*a.speed;for(let b of this.agents){if(b===a)continue;let dd=distance(a.position,b.position);if(dd<.58&&dd>.005){let repel=(.58-dd)*2.2;vx+=(a.position.x-b.position.x)/dd*repel;vz+=(a.position.z-b.position.z)/dd*repel}}let length=Math.hypot(vx,vz),cap=a.speed;if(length>cap){vx*=cap/length;vz*=cap/length}let next={x:a.position.x+vx*dt,z:a.position.z+vz*dt};if(this.nav.walkable(next)&&this.nav.clearLine(a.position,next)){let travel=distance(next,a.position);a.position=next;a.heading=Math.atan2(vx,vz);a.moving=travel>.001;a.blockedTime=travel<dt*a.speed*.2?a.blockedTime+dt:0}else a.blockedTime+=dt;if(a.blockedTime>1.2)this.replan(a,true)
  }}
 snapshot(){return this.agents.map(a=>({id:a.id,state:a.state,activity:a.task?.kind||'thinking',site:a.task?.siteId||null,position:{...a.position},path:a.path.map(p=>({...p})),needs:{...a.needs},decisions:a.decisions,completed:a.completed,replans:a.replans}))}
}
